namespace WeCodeArt\Support\Plugins\RankMath\Blocks;

defined( 'ABSPATH' ) || exit;

use WeCodeArt\Config\Traits\Singleton;
use WeCodeArt\Gutenberg\Blocks\Dynamic;
use function WeCodeArt\Functions\get_prop;

/**
 * Gutenberg RankMath TOC block.
 */
class TOC extends Dynamic {

	use Singleton;

	/**
	 * Block namespace.
	 *
	 * @var string
	 */
	protected $namespace = 'rank-math';

	/**
	 * Block name.
	 *
	 * @var string
	 */
	protected $block_name = 'toc-block';

	/**
	 * Block args.
	 *
	 * @return 	array
	 */
	public function init() {
		\add_filter( 'render_block_' . $this->get_block_type(), [ $this, 'render' ], 20, 1 );
	}

	/**
	 * Block args.
	 *
	 * @return 	array
	 */
	public function block_type_args(): array {
		return [ 
			'style' => [ $this->get_asset_handle(), 'wp-block-details' ]
		];
	}

	/**
	 * Get block asset handle.
	 *
	 * @return string
	 */
	public function get_asset_handle(): string {
		return $this->namespace . '-' . $this->block_name;
	}

	/**
	 * Dynamically renders the Rank Math table of contents block.
	 *
	 * @param 	string 	$content 	The block markup.
	 *
	 * @return 	string 	The block markup.
	 */
	public function render( string $content = '' ): string {
		$dom	= wecodeart( 'dom' )::create( $content );
		$block	= wecodeart( 'dom' )::get_elements_by_class( $dom, 'wp-block-rank-math-toc-block', '*', 0 );

		if ( ! $block || 'details' === strtolower( $block->tagName ) ) {
			return $content;
		}

		$details = wecodeart( 'dom' )::change_tag( $block, 'details' );

		if ( ! $details ) {
			return $content;
		}

		$title = $details->firstChild;

		while ( $title && ! ( $title instanceof \DOMElement ) ) {
			$title = $title->nextSibling;
		}

		$summary	= wecodeart( 'dom' )::create_element( 'summary', $dom );

		if ( ! $title || ! $summary ) {
			return $content;
		}

		wecodeart( 'styles' )->Utilities->load( [ 'my-0' ] );
		wecodeart( 'dom' )::add_classes( $title, [ 'rank-math-toc-title', 'my-0' ] );
		$classes = wecodeart( 'dom' )::get_classes( $details );
		$classes = array_values( array_unique( array_merge( [ 'wp-block-details' ], $classes ) ) );
		$details->setAttribute( 'class', implode( ' ', $classes ) );

		if ( array_intersect( [ 'open', 'is-open' ], $classes ) ) {
			$details->setAttribute( 'open', '' );
		}

		$details->insertBefore( $summary, $title );
		$summary->appendChild( $title );

		return $dom->saveHTML();
	} 

	/**
	 * Block styles
	 *
	 * @return 	string 	The block styles.
	 */
	public function styles() {
		return '';
	}
}
